-- 20260704e_i18n_calibraciones_translations.sql
-- FASE 3 i18n — traducción al inglés de las 60 fases de Calibración (libreria_protocolos).
-- Generado desde el export vivo + traducción por-pilar con verificación adversarial.
-- tareas_json_en usa el MISMO patrón que tareas_json (to_jsonb(json_build_array(...)::text))
-- → el cliente lo parsea idéntico. Keyed por id de fase; ids de tarea preservados y en orden.
-- Pegar en Supabase Dashboard → SQL Editor → Run.

BEGIN;
-- EMOCIONAL · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$EMERGENCY SEAL$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your emotional world is in collapse. You react to everything automatically, you feel like a victim of what happens, and anxiety runs the show. You lose energy constantly at any tension or outside stimulus.$rsv$, sugerencia_text_en = $rsv$Add these small anchors to stop the energy leak and start creating a space of calm between what the environment triggers in you and your reaction.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e1_1$rsv$,'desc',$rsv$Pause Rule (Reaction Cutoff): At any stimulus that rattles you (a message, a criticism, a stressful situation), you are forbidden to respond with words or on your phone for 3 minutes. Move the device away or take a step back. Force your system to settle before acting.$rsv$), json_build_object('id',$rsv$e1_2$rsv$,'desc',$rsv$Complaint Fast: Forbidden to say the same problem, complaint, or pain out loud more than twice in the same day. Cutting the verbal repetition breaks the victim loop and keeps you from contaminating your own energy.$rsv$), json_build_object('id',$rsv$e1_3$rsv$,'desc',$rsv$Anesthesia Watch: Identify your main escape route from pain or stress (for example: endless scrolling, food, shopping). When you feel the urge to escape, stop for 60 seconds with your eyes closed before giving in. Feel the emptiness you are trying to fill.$rsv$))::text) WHERE id = '33a399e2-997f-4481-9fe5-9be1e9e83ba2';
-- EMOCIONAL · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ARMOR SHUTDOWN$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You live on the defensive. Your system operates assuming the world is a constant threat, which creates chronic tension, resistance, and a suffocating dependence on the approval of others just to stay upright.$rsv$, sugerencia_text_en = $rsv$Apply these anchors daily to relax your nervous system, drop the weight of the shield, and start draining the fear of rejection.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e2_1$rsv$,'desc',$rsv$Strict Approval Diet: Turn off every notification from social or messaging apps that feeds your need for approval (likes, views). Enter the platforms only when they serve a concrete purpose, not to scan what people think of you.$rsv$), json_build_object('id',$rsv$e2_2$rsv$,'desc',$rsv$Drop the Rescuer (Guard Your Energy): During your interactions today, avoid giving advice, solutions, or trying to "fix" other people's emotional pain unless they ask you directly in words. Observe, listen, but do not drain yourself.$rsv$), json_build_object('id',$rsv$e2_3$rsv$,'desc',$rsv$Question the Projection: When an interaction offends you or makes you feel rejected, before you defend yourself, repeat this phrase in your mind: "What part of me believes this is true?". Return the authority to your center, not to whoever said it.$rsv$), json_build_object('id',$rsv$e2_4$rsv$,'desc',$rsv$Ground the Uncertainty: When anxiety about the future speeds up your thoughts, write down on paper the worst scenario you imagine, then cross it out with a single line. Pull the fear out of your mind and force it to become ink, so it loses its abstract power.$rsv$))::text) WHERE id = '9a99e36d-86e3-4ca8-88bb-56b2f9ed132b';
-- EMOCIONAL · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$STABILIZING THE PENDULUM$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your emotions swing hard. Your body confuses the intensity of drama with feeling alive. Your energy rises and falls nonstop, draining your reserve as you chase approval in desperation or react to outside tension.$rsv$, sugerencia_text_en = $rsv$Anchor these practices to get off the emotional roller coaster. The goal is to stabilize your center and recover the energy you are handing to the environment.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e3_1$rsv$,'desc',$rsv$Algorithm Detox: Limit passive consumption (scrolling) on social media to a single 30-minute window per day. Cutting the constant comparison and the exposure to other people's emotions stabilizes your own measure of worth.$rsv$), json_build_object('id',$rsv$e3_2$rsv$,'desc',$rsv$Pause in Conflict: During an argument, give up having the "last word". When the verbal tension heats up, remove yourself physically from the place. Do not respond until your breathing is deep and rhythmic again.$rsv$), json_build_object('id',$rsv$e3_3$rsv$,'desc',$rsv$Stop the Pendulum: When you feel extreme euphoria or deep sadness, stop and make no decision about money, relationships, or work. Force yourself to wait 24 hours. You must only act from calm.$rsv$), json_build_object('id',$rsv$e3_4$rsv$,'desc',$rsv$Close the Complaint Leak: Stop using drama and suffering to connect with other people (bonding over shared pain). Steer your conversations today toward growth, projects, and creation.$rsv$))::text) WHERE id = 'aea0e2c0-94ce-4277-87b6-380acf2f3dc0';
-- EMOCIONAL · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$PURGE OF FALSE LIGHT$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have a mirage of control (toxic containment). You repress difficult emotions to keep up a facade of "peace" or moral superiority. That false light creates acidity in your body, tension in your neck, and deep blocks in your nervous system.$rsv$, sugerencia_text_en = $rsv$Apply these directives to release the pressure in your system. True coherence is not reached by repressing what hurts, but by processing it without fear of breaking the image others hold of you.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e4_1$rsv$,'desc',$rsv$Raw Expression Valve: Create a 100% safe and private space (a notebook you can destroy or voice notes you delete instantly). Write or record your difficult emotion (anger, envy, pain) with no "spiritual" filters. Get the poison out before it turns into illness.$rsv$), json_build_object('id',$rsv$e4_2$rsv$,'desc',$rsv$Tension Release: Three times a day, check the tension in your jaw, shoulders, and stomach. If you notice you are holding on, release it by exhaling hard through your mouth (a deep sigh). Drop the physical weight of holding up your social mask.$rsv$), json_build_object('id',$rsv$e4_3$rsv$,'desc',$rsv$Precise Confrontation: Identify a boundary you have not set or an uncomfortable conversation you avoid to "not make drama". Communicate it this very week in a neutral, direct way. Do not apologize for taking up space or try to convince the other person.$rsv$), json_build_object('id',$rsv$e4_4$rsv$,'desc',$rsv$Drop the "Evolved One": In front of your close circle, give up the load of being "the one who is always fine", "the strong one", or "the one who never gets angry". Allow yourself to be someone in progress and embrace conflict as a tool to build.$rsv$))::text) WHERE id = 'aa20fad3-592c-498a-b254-788fb0aa8c8e';
-- EMOCIONAL · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$UNLOCKING THE OBSERVER$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You overthink and never move to action. You understand perfectly where your wounds come from and analyze your emotions in detail, but you use that over-analysis as a new way to avoid the action that would trigger real change.$rsv$, sugerencia_text_en = $rsv$Apply these anchors to move the energy of your analytical mind into concrete action. This is the exact moment to stop observing the tension and start transforming it.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e5_1$rsv$,'desc',$rsv$Cut the Verbal Loop: Forbidden to "process" the same emotional topic with friends, therapist, or partner more than once. If you already understood the origin of the problem, talking it through a second time drains you; the only valid path now is action.$rsv$), json_build_object('id',$rsv$e5_2$rsv$,'desc',$rsv$Action That Transforms: For every hour you spend feeling anxious about the future or analyzing a past pain, immediately execute 15 minutes of creation or concrete work (coding, designing, training). Turn the mental weight into energy that moves.$rsv$), json_build_object('id',$rsv$e5_3$rsv$,'desc',$rsv$Close Circle Audit: Review the 5 people you spend the most time with. If any of them puts you on alert or forces you to dim yourself to fit in, cut your time with them in half this very week.$rsv$), json_build_object('id',$rsv$e5_4$rsv$,'desc',$rsv$Give Up on Justice: In the face of a betrayal or someone else's mistake, stop waiting for the other person to "realize" or ask for forgiveness. Cancel the debt inside. Let the topic go to free up space in your mind.$rsv$))::text) WHERE id = 'a12bb0ca-2c9e-4097-bc58-9b07912581dd';
-- EMOCIONAL · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$MEMBRANE RUPTURE (BOUNDARIES)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your sovereignty is in transition, with some residual tension. You are starting to set boundaries and protect your space, but guilt and a subtle fear of disconnection still make you lose energy and leave you heavy afterward.$rsv$, sugerencia_text_en = $rsv$Apply these directives to shield your borders with compassionate firmness. You do not ask permission to protect your energy: you hold it with authority and without remorse.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e6_1$rsv$,'desc',$rsv$The "No" Without Explanation: Decline at least one invitation, request, or favor per week using only the words "No, thank you" or "That isn't possible for me right now". You are forbidden to give explanations, excuses, or justifications to soften the boundary.$rsv$), json_build_object('id',$rsv$e6_2$rsv$,'desc',$rsv$Uninstall the Guilt: Every time you set a boundary and feel guilt, repeat this anchoring phrase: "By protecting my energy, I lift all my people. Saving others at the cost of my energy only depletes me".$rsv$), json_build_object('id',$rsv$e6_3$rsv$,'desc',$rsv$Melancholy Purge (Physical Release): Identify an object, a photo, a contact in your phone, or a physical keepsake that ties you to a dead cycle (a relationship or a past identity). Destroy it, delete it, or throw it in the trash today. Free up the space.$rsv$), json_build_object('id',$rsv$e6_4$rsv$,'desc',$rsv$Raw Observation: When a deep pain tries to surface, do not analyze it or run. Sit in total silence for 10 minutes. Feel where in your body (chest, throat, stomach) that heaviness lodges. Look at it head-on until the sensation dissolves on its own.$rsv$))::text) WHERE id = 'afbea4ed-c77e-45f6-9778-8712a3011973';
-- EMOCIONAL · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CONDITIONED SOVEREIGNTY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your field is stable, but still permeable to close-range hits. What outside people think has stopped mattering to you, but criticism or tension from your inner circle (family, partner, business partners) still manages to slip in and disrupt your rhythm for a while.$rsv$, sugerencia_text_en = $rsv$Apply these calibrations to reinforce your shield at the intimate level. The goal is that not even hits from your circle of origin can move your center, shifting from controlled reaction to active calm.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e7_1$rsv$,'desc',$rsv$Disconnect From Close Drama: Formally give up trying to wake up the people in your inner circle who prefer to stay in the heaviness. Allow them to live at their level without trying to pull them up to yours. Their process is not your responsibility.$rsv$), json_build_object('id',$rsv$e7_2$rsv$,'desc',$rsv$Filter the Criticism: Set a strict rule: you will only accept criticism or feedback from people who operate at a level equal to or higher than yours. Everything else you classify as noise and ignore.$rsv$), json_build_object('id',$rsv$e7_3$rsv$,'desc',$rsv$Pause After a Deep Hit: When a betrayal, conflict, or hard clash happens with someone in your first circle, impose an absolute 24-hour communication cutoff. There is no discussion while the system is hot. You only operate from calm.$rsv$), json_build_object('id',$rsv$e7_4$rsv$,'desc',$rsv$Release Your Identity (Update the Program): Detect a positive label you have given yourself ("I'm the smart one", "I'm the peaceful one", "I'm the spiritual one") that forces you to behave a certain way. Break it. You are a consciousness that changes, not a fixed identity.$rsv$))::text) WHERE id = 'abfb6d70-7eb6-478c-96e4-cfb66f41f964';
-- EMOCIONAL · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ACTIVE ALCHEMY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have high coherence. Your shield is sealed. Pain is no longer suffering: you use it as pure information. Your system is highly efficient, but it needs to master instant transformation to turn what is difficult outside directly into creation and expansion.$rsv$, sugerencia_text_en = $rsv$Apply these high-impact anchors to hold your light in draining environments without losing stability. You are the one who alters the space, not the space that alters you.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e8_1$rsv$,'desc',$rsv$Immersion in Controlled Tension (Clean Containment): Interact on purpose in a highly draining environment or with a highly draining person. Your only task is to hold your breath through your nose and your calm without absorbing a single drop of their exhaustion. Observe with compassion, but keep your border sealed.$rsv$), json_build_object('id',$rsv$e8_2$rsv$,'desc',$rsv$Extract the Lesson Instantly: In the face of any material or relationship loss, cancel the mourning. Immediately write down 3 lessons that tension left you, and reframe the loss in your mind as "space freed for something new".$rsv$), json_build_object('id',$rsv$e8_3$rsv$,'desc',$rsv$Strategic Surrender (Trust the Uncertain): Identify a project, outcome, or person you are over-controlling out of anxiety about the future. Release control of the final result today. Focus only on executing your daily actions and allow life to arrange the best outcome.$rsv$), json_build_object('id',$rsv$e8_4$rsv$,'desc',$rsv$Hold the Good (Conscious Expansion): When you experience a peak of success, financial abundance, or deep peace, notice if the "feeling that you don't deserve it" or the fear of losing it shows up. Stay there. Breathe inside that light and force yourself to tolerate well-being without sabotaging it.$rsv$))::text) WHERE id = '2c435e51-e7bb-4842-8aad-0759ff8cf7aa';
-- EMOCIONAL · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$HOLOGRAPHIC SHIELD$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your tension is minimal. The environment and outside opinion no longer have authority over your center. Your system tolerates high levels of expansion, but it needs final anchors to erase any trace of subtle self-sabotage or unconscious loyalty to pain.$rsv$, sugerencia_text_en = $rsv$Apply these master directives to operate as a detached observer. At this point, pain, chaos, and joy are simply different forms of energy that you use to build the reality you desire.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e9_1$rsv$,'desc',$rsv$Erase the Past: In the face of any memory of a past mistake or failure, cancel the guilt instantly by treating it as an "old program". Recognize that the version of you who made that mistake no longer exists.$rsv$), json_build_object('id',$rsv$e9_2$rsv$,'desc',$rsv$Expand Your Border of Light: When you receive a massive inflow of abundance (money, recognition, pure love), block the "feeling that you don't deserve it". Force yourself to do nothing to "compensate for it". Breathe, expand your body, and recognize that it is the logical result of what you built.$rsv$), json_build_object('id',$rsv$e9_3$rsv$,'desc',$rsv$Neutrality Before Chaos: Observe the collapse, drama, or chaos of the outside world (news, social conflicts, other people's crises) without issuing a single moral judgment and without spending a drop of energy trying to correct it. Contemplate the game without stepping onto the field.$rsv$), json_build_object('id',$rsv$e9_4$rsv$,'desc',$rsv$Close Without Delay: If a project, relationship, or stage reaches its natural end, close the door that same day. Give thanks for what you learned and free up the space immediately, without a single hour of dwelling or melancholy.$rsv$))::text) WHERE id = 'b302bee4-5b37-4e75-9e2c-6c816668a2a9';
-- EMOCIONAL · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SUPERCONDUCTIVITY (ZERO STATE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your emotional world operates in zero friction. Absolute active calm. Provocation disintegrates on touching your field. You are the unbreakable center of the hurricane, transforming any outside drain into the will to create in an instant.$rsv$, sugerencia_text_en = $rsv$You have reached the Emotional Zero State. You are the architect of your own life. Your only task now is to radiate this coherence, keeping your energy closed within itself and operating from total calm.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$e10_1$rsv$,'desc',$rsv$Absolute Surrender to Calm: Release any attempt to predict or control how your visions will manifest. Operate with absolute certainty about the final destination (the "what") and allow life to arrange the best path (the "how") without putting up resistance.$rsv$), json_build_object('id',$rsv$e10_2$rsv$,'desc',$rsv$Instant Transformation (Zero Processing Time): In the face of any hit, loss, or direct attack, cancel the suffering time. Absorb the tension, extract the lesson, and turn it into creative energy in the very instant it touches your field.$rsv$), json_build_object('id',$rsv$e10_3$rsv$,'desc',$rsv$The Mirror: When you interact with people in deep darkness or suffering, hold your light without moving inside. You are a lighthouse that does not waver; you do not go down into the cave to save anyone, you simply light the exit for whoever decides to come up.$rsv$), json_build_object('id',$rsv$e10_4$rsv$,'desc',$rsv$Permanent Sovereignty: Remember and anchor at every instant that your worth, your peace, and your abundance are already approved from the source. You are not an effect of the environment; you are the cause of your environment.$rsv$))::text) WHERE id = 'a2dfae45-efdc-4001-a428-46825a5e0c62';
-- FINANCIERO · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$STRUCTURAL TOURNIQUET (HEMORRHAGE SEAL)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$There is a collapse in your finances and total exhaustion. Your nervous system associates money with danger, scarcity, or pain. You depend on a single source of income (something very fragile) and you spend constantly to cover emotional gaps.$rsv$, sugerencia_text_en = $rsv$Add these small anchors to your day to stop the loss of energy and money. The immediate goal is not to earn more, but to stop draining yourself out of inertia.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$g1$rsv$,'desc',$rsv$Look at your numbers: You are forbidden to hide from your accounts. Open your bank app every day at the same time, for exactly 60 seconds. Watch the balance in total silence. Breathe through your nose. Train your nervous system to see your numbers without panicking.$rsv$), json_build_object('id',$rsv$g2$rsv$,'desc',$rsv$The 24-hour rule: When you feel the urge to buy any item, service, or food that is not strictly vital, wait 24 hours. Let the emotion of the moment cool off; if tomorrow, with a clear head, you see it is not useful, do not buy it.$rsv$), json_build_object('id',$rsv$g3$rsv$,'desc',$rsv$Cut one leak: Identify and cancel today at least one recurring charge that drains your account every month without giving you anything in return (apps you do not use, platforms you do not watch, plans you forgot about).$rsv$), json_build_object('id',$rsv$g4$rsv$,'desc',$rsv$Change your language: Forbid yourself from saying and thinking phrases like "I'm broke", "I have no money", or "that's too expensive for me". Replace them with: "That expense is not a priority for me right now".$rsv$))::text) WHERE id = '0375081e-22dc-4442-a895-bb35f814a732';
-- FINANCIERO · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SURVIVAL DECOMPRESSION$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You carry a dense heaviness. You work with extreme effort, sacrificing your vitality to earn the bare minimum. If you save money, it is not out of strategy, but out of pure fear of ending up at zero.$rsv$, sugerencia_text_en = $rsv$Execute these steps daily to start separating the emotional weight from each transaction. You need to teach yourself that money is a flow that needs to move, not a treasure to be hoarded out of terror.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f2_1$rsv$,'desc',$rsv$Release as you pay: At the exact moment you make a payment (cash or digital), relax your stomach and jaw. Release your breath and repeat inside: "I release this energy to keep everything in motion. Life returns it to me multiplied".$rsv$), json_build_object('id',$rsv$f2_2$rsv$,'desc',$rsv$Set aside 1%: No matter how much you earn or how much debt you have, set aside 1% of all the money that comes in and send it to an untouchable account. It is not an emergency fund; it is an act to prove to yourself that you have the power to retain money by your own choice.$rsv$), json_build_object('id',$rsv$f2_3$rsv$,'desc',$rsv$How much your hour is worth: Grab paper and pencil. Divide your monthly income by the real hours you give to work (including commutes and everything you keep thinking about at home). Look with the cold detachment of numbers at how much vitality you are trading for each peso.$rsv$), json_build_object('id',$rsv$f2_4$rsv$,'desc',$rsv$Zero debt for pleasures: You are strictly forbidden from using credit (future money) to pay for today's pleasures (meals, clothes, trips). If the money does not exist in your account now, you are not allowed to make that expense.$rsv$))::text) WHERE id = 'f3eccc41-8bf4-4ec6-b888-b160410736db';
-- FINANCIERO · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$AXIS STABILIZATION (BREAKING THE SLAVERY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$There is mechanical slavery and friction in every exchange. Your body generates money, but the transaction comes loaded with resentment or guilt. Your identity rises and falls with the numbers on your screen, and your energy drains from trying to please others.$rsv$, sugerencia_text_en = $rsv$Anchor these calibrations to break the inertia of working out of pure obligation. The goal is to separate your worth as a person from your bank balance and stop negotiating your energy from the fear of losing an income.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f3_1$rsv$,'desc',$rsv$You are not the number: Every time you check your accounts or receive a payment, repeat out loud: "This is data, it is not me. My worth is absolute; the number is just a calculation". Separate the one who observes from the data on the screen.$rsv$), json_build_object('id',$rsv$f3_2$rsv$,'desc',$rsv$Do not lower your price out of fear: The next time someone questions what you charge for your work or your time, you are forbidden from lowering it instantly to "save" the deal. Hold the silence. Let the discomfort fall on the other party; defend your worth without justifying yourself.$rsv$), json_build_object('id',$rsv$f3_3$rsv$,'desc',$rsv$Cut what drains you: If you have a source of income that pays you less than your effort is worth and weighs on you every day, set an expiration date for it today. Build a 30- or 60-day plan to change that situation and free up space for something better.$rsv$), json_build_object('id',$rsv$f3_4$rsv$,'desc',$rsv$Stop giving away your work: Stop giving your time, your knowledge, or your help for free to those who do not value it. What you know and what you do is condensed energy; if you hand it over without a fair exchange (in money or in real value), you are draining yourself.$rsv$))::text) WHERE id = '681b0264-1727-4d2e-990a-b1afb067e371';
-- FINANCIERO · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$BREAKING THE MIRAGE (CONDITIONED STABILITY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have reached the edge of your comfort zone. You already have stability and cover your needs, but you manage your money passively. The money sits still. The entire flow depends 100% on you moving; if you stop, the income falls.$rsv$, sugerencia_text_en = $rsv$Execute these directives to give your money momentum. You need to understand that comfort is wear disguised, and that staying still out of conformity holds back your growth.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f4_1$rsv$,'desc',$rsv$Put the idle money to work: Identify the money you have "stashed under the mattress" (literal or digital) that loses value by sitting still. Take a safe percentage of that dormant money and put it into something that expands your capacity (a course that gives you more value, a work tool, a good book, new equipment). Let your money work for you.$rsv$), json_build_object('id',$rsv$f4_2$rsv$,'desc',$rsv$Raise your rate by 10-15%: Take what you charge for your work, your service, or your time and raise it by 10% to 15% this very week. Do not ask anyone for permission; simply update your price and watch how everything rearranges around your new stance. (If you work for a fixed salary, prepare and schedule the conversation to ask for what you deserve.)$rsv$), json_build_object('id',$rsv$f4_3$rsv$,'desc',$rsv$Plant a second income: Invest at least 2 hours a week designing a second source of income that does not depend on your time (something you can sell, an extra service, a small side project). Start building your independence beyond your main income.$rsv$), json_build_object('id',$rsv$f4_4$rsv$,'desc',$rsv$Overcome laziness: Notice the drowsiness of your comfort. When you feel too lazy to do something that would multiply your abundance because "you're fine as you are", apply the 5-second rule: count backward from 5 and force your body to start the action before you reach zero.$rsv$))::text) WHERE id = 'e6635250-fae9-433f-bf07-4a242b4d35dc';
-- FINANCIERO · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$VALUE TRANSITION (THE MAGNETIC AWAKENING)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You are starting to separate from who you were. You recognize the urgency of no longer depending on a single source, but your body still races or hesitates a little when it comes to communicating your true worth. Impostor syndrome is still there, latent.$rsv$, sugerencia_text_en = $rsv$Execute these calibrations to train your body to hold higher figures without your pulse trembling. It is time to eliminate the shame of charging.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f5_1$rsv$,'desc',$rsv$Quote with vertigo: On your next proposal or when you set a price for something, put a number that gives you a slight vertigo. If setting it does not make your palms sweat a little, you are charging below your level. Make the other person rise to your level, not the other way around.$rsv$), json_build_object('id',$rsv$f5_2$rsv$,'desc',$rsv$Invest in yourself: Take a percentage of your idle money and devote it to building what is yours. Stop funding other people's projects and start putting that money into you: into learning something that makes you worth more, into a tool that propels you, or into any idea of your own you want to get off the ground.$rsv$), json_build_object('id',$rsv$f5_3$rsv$,'desc',$rsv$Rejection is a filter: When someone rejects your new rate, forbid yourself from feeling loss or that you are not enough. Read it instantly in another way: your high price worked perfectly as a filter to keep the situations that do not suit you out of your path.$rsv$), json_build_object('id',$rsv$f5_4$rsv$,'desc',$rsv$Review where your income comes from: Draw how your income comes in today. If a single source represents more than 60% of your accounts, declare a state of alert. Design a 90-day plan today to spread that weight and safeguard your independence.$rsv$))::text) WHERE id = '3d7bff32-bd9d-403f-b021-19eb546efd36';
-- FINANCIERO · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$GRAVITATIONAL LIFTOFF (TACTICAL ALLOCATION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The guilt around charging has disintegrated. You operate with certainty and allocate your resources with purpose. The risk here is stagnation: you need to upgrade your tools, your equipment, and your mind to handle the new workloads without a bottleneck forming.$rsv$, sugerencia_text_en = $rsv$Implement these directives to treat yourself as a high-efficiency system. Money stops being an end in itself and becomes a tool to build the future you want.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f6_1$rsv$,'desc',$rsv$Invest in your body and your tools: Set aside an untouchable fund only to improve what you use to work and to take care of yourself. Put money directly into whatever accelerates your work (better equipment, better tools) and into the non-negotiable of your good hydration and your silicon supplementation. Your body and your tools are what yield the most.$rsv$), json_build_object('id',$rsv$f6_2$rsv$,'desc',$rsv$Set a clear and firm price: Eliminate the idea of charging differently based on what each person can pay. Your work and your time are worth an exact figure. Set what you charge and hold it as a wall no one can move.$rsv$), json_build_object('id',$rsv$f6_3$rsv$,'desc',$rsv$Attract, do not chase: Stop every action that involves "chasing" money or convincing people. Invest that energy in growing your own center: improving what you do, learning, building what is yours. A sun does not chase the planets; it simply grows in size and the orbit of the planets adjusts on its own.$rsv$), json_build_object('id',$rsv$f6_4$rsv$,'desc',$rsv$Seal the leaks: Review your accounts from the last 30 days. If you detect money going into quick consumption, food that does not nourish you, or distractions, close that channel. Every peso in your account is energy that must sustain your direction, not fund your wear.$rsv$))::text) WHERE id = '079dd878-c131-44a1-965f-5a49fee66bbf';
-- FINANCIERO · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$OPERATIONAL SOVEREIGNTY (DECENTRALIZED ARCHITECTURE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have completely detached from the emotional weight of each transaction. Money is just data. The days of low liquidity no longer disturb your peace or make you doubt your vision. You have several sources of income up and running, but you still need to step in yourself to keep everything going.$rsv$, sugerencia_text_en = $rsv$Execute these calibrations so your money and your work flow more on their own. The goal is for your value to circulate and generate returns without you having to wear yourself down on small tasks.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f7_1$rsv$,'desc',$rsv$Let go of maintenance: Identify where your time goes on repetitive, small tasks (the usual messages, paperwork, recurring to-dos). Simplify them, prepare ready-made replies, or ask for help with them. Your mind must stay focused on what truly adds, not on what merely maintains.$rsv$), json_build_object('id',$rsv$f7_2$rsv$,'desc',$rsv$Set a wall of quality: Establish a minimum standard for what you agree to do. Say no to what pays you little and takes a lot from you. If something does not deserve your best effort or your time, turn it down. Protect your level.$rsv$), json_build_object('id',$rsv$f7_3$rsv$,'desc',$rsv$Income that comes in on its own: If you create something that sells by itself (a course, a book, a digital product, a template), set up the sales and delivery process so the payment and everything happen in a closed cycle, without you having to be present every time. If you do not have something like that yet, now is the moment to start designing it.$rsv$), json_build_object('id',$rsv$f7_4$rsv$,'desc',$rsv$Absence test: Disappear from work for 3 full days (zero emails, zero to-dos, zero replies). Observe which parts of your economy collapse and which keep generating income. That shows you exactly where the weak link in your network is.$rsv$))::text) WHERE id = '3a2f88d6-e69f-43cc-9cb0-deb32d0a72dc';
-- FINANCIERO · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$AUTHORITY MAGNETISM (10X PREPARATION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$What you do is starting to set the standard around you. You charge from absolute certainty and people respond. You are one step away from a huge leap, but you need to widen your legal, practical, and mental foundations so that an income 10 times larger does not blow up your structure.$rsv$, sugerencia_text_en = $rsv$Implement these steps to reinforce your structure before the big leap. When massive abundance arrives, your system must be an unbreakable container.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f8_1$rsv$,'desc',$rsv$Withstand the pressure (stress test): Imagine that tomorrow your income multiplies by 10. Would your organization, your accounts, and your habits withstand that hit, or would they overflow? Do you know where that money would go, how you would take care of it, and how you would sustain the pace? Prepare your capacity and your mind today to sustain a much larger income, in whatever you do.$rsv$), json_build_object('id',$rsv$f8_2$rsv$,'desc',$rsv$Charge for your value, not for the hours: Drop once and for all the idea of justifying what you charge only by the time it takes you. What you charge no longer covers the hours; it covers your unique signature, your experience, and the authority of what you deliver. Your price is a filter for access to you.$rsv$), json_build_object('id',$rsv$f8_3$rsv$,'desc',$rsv$Get used to the big figure: Write on your wall or your phone the exact monthly figure that represents a 10-times-larger leap for you. Look at it every day until the number stops surprising, thrilling, or dizzying you. Train your nervous system to see that amount as normal, before it even reaches your account.$rsv$), json_build_object('id',$rsv$f8_4$rsv$,'desc',$rsv$Release the guilt of earning: When you start earning in a day what others around you earn in months, your mind will try to generate guilt. Cut it at the root. Realize that your abundance takes nothing from anyone; on the contrary, the stronger your center, the more light and resources you contribute to your surroundings (your people, what you build).$rsv$))::text) WHERE id = '2bea5ed8-7b56-4c52-9e18-8d1fd3fae55a';
-- FINANCIERO · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CENTER OF GRAVITY (LIVING ARCHITECTURE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your tension with money is nearly gone. You stopped trading your time for money. What you built generates income on its own. Money comes in even while your body rests.$rsv$, sugerencia_text_en = $rsv$Execute these master directives to scale the impact of what you do. It is no longer about securing your independence, but about funding and expanding your vision at a larger scale.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f9_1$rsv$,'desc',$rsv$Effortless income: Eliminate any inner idea that ties "physical effort" to "money as a result". Watch how money comes into your account without you lifting a finger, thanks to what you already left built. Normalize charging for what you created, not for the sweat of your brow.$rsv$), json_build_object('id',$rsv$f9_2$rsv$,'desc',$rsv$Build the future you imagine: The money you accumulate now is a tool to design at a large scale. Devote resources to making your vision real, whatever it is for you: helping your people, launching a project that excites you, or creating something that leaves a mark. You decide what the future looks like.$rsv$), json_build_object('id',$rsv$f9_3$rsv$,'desc',$rsv$Immune to crises: Watch the world's economic crises (inflation, markets) from above. Your economy sustains itself. Forbid yourself from entering the collective panic; the scarcity out there has no permission to penetrate your shield.$rsv$), json_build_object('id',$rsv$f9_4$rsv$,'desc',$rsv$Contribute from abundance: When you collaborate or contribute to others, do it from over-abundance. Deliver a great deal of value without fear of "ending up empty". You know your capacity to generate good ideas is infinite.$rsv$))::text) WHERE id = '92be497b-3398-4c2e-a48c-6652ce37c10c';
-- FINANCIERO · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SINGULARITY OF ABUNDANCE (ZERO STATE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$There is zero tension in your economic engine. You multiply with total ease. Money has lost all its weight and works only as a luminous data point. Large incomes no longer surprise you; the yes to money happens in your mind before it appears in the bank.$rsv$, sugerencia_text_en = $rsv$You have reached the economic Zero State. You are the bank, the antenna, and the architect. Your only task is to hold the creative space and direct your resources with total precision to manifest exactly your vision.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f10_1$rsv$,'desc',$rsv$Let it flow, do not hoard: Dissolve the instinct to save out of fear. In the Zero State you understand that your greatest strength lies in being an impeccable channel: energy comes in, nourishes the system, and goes out right away to create new networks. Money that stagnates rots. Be the fastest and cleanest channel.$rsv$), json_build_object('id',$rsv$f10_2$rsv$,'desc',$rsv$Leap, do not grow in small steps: Give up gradual growth models. Command large leaps on your path. If you need resources for something enormous, do not calculate them over 5 years; build the structure, hold absolute certainty, and allow the money to arrive in unexpected ways.$rsv$), json_build_object('id',$rsv$f10_3$rsv$,'desc',$rsv$The same calm with little or with a lot: Live the arrival of 10 pesos or 10 million with exactly the same calm in your chest. Thank the transaction with neutrality. Your ego does not inflate with material success because it knows that the millions are simply the physical result of good work.$rsv$), json_build_object('id',$rsv$f10_4$rsv$,'desc',$rsv$You are the source: Recognize every second that you are the source of all your income. No client, no platform, and no external network "gives" you money. All the money that exists in your life is a direct reflection of your own consciousness. Your source of wealth is inexhaustible, because the source is you.$rsv$))::text) WHERE id = '6b3d0c5c-68be-4c5b-9150-9bdbe8ccda91';
-- FISICO · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SYSTEM RESCUE$rsv$, descripcion_corta_en = $rsv$Emergency protocol to restore your body's temperature and energy.$rsv$, alerta_text_en = $rsv$Your body is in deep exhaustion. It runs in survival mode: everything takes more effort and you lose energy at every moment.$rsv$, sugerencia_text_en = $rsv$Add these small anchors to your day to stop the energy leak and reignite your baseline vitality. Do not chase perfection: chase consistency.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f1$rsv$,'desc',$rsv$Startup Valve: Drink 500 ml of water (ideally with a pinch of sea salt) within the first 30 minutes after waking, before eating or taking any stimulant (coffee/sugar).$rsv$), json_build_object('id',$rsv$f2$rsv$,'desc',$rsv$Mechanical Unlock: Do 5 minutes of continuous joint rotations (neck, shoulders, hips, wrists, ankles) at any point in the day to pull your body out of stiffness.$rsv$), json_build_object('id',$rsv$f3$rsv$,'desc',$rsv$Rest Perimeter: Move your phone more than 2 meters away from your bed and set it to Airplane Mode at least 30 minutes before closing your eyes.$rsv$))::text) WHERE id = '079da96f-f828-448b-9cc1-ca7c19cb71cf';
-- FISICO · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$PRIMARY IGNITION$rsv$, descripcion_corta_en = $rsv$Protocol to restore your body's temperature and energy.$rsv$, alerta_text_en = $rsv$Your body carries heaviness. It runs on energy debt and depends on external stimulants (coffee, sugar) to stay awake.$rsv$, sugerencia_text_en = $rsv$Do these calibrations every day to switch on your body's natural sensors and start drawing clean energy from your surroundings.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f2_1$rsv$,'desc',$rsv$Light Injection: Expose your skin and eyes (no glasses or lenses in between) to direct sunlight for at least 10 minutes within the first hour after waking.$rsv$), json_build_object('id',$rsv$f2_2$rsv$,'desc',$rsv$Window Closure: Stop eating exactly 2 hours before sleep, so your body repairs itself instead of continuing to digest.$rsv$), json_build_object('id',$rsv$f2_3$rsv$,'desc',$rsv$Coherence Pause: Take 5 deep, rhythmic breaths through the nose only before your heaviest meal of the day, to shift your nervous system from alert to digestion.$rsv$), json_build_object('id',$rsv$f2_4$rsv$,'desc',$rsv$Habit Cleanup: Identify and replace one single synthetic product you use daily (e.g., commercial deodorant or fluoride toothpaste) with a more natural alternative.$rsv$))::text) WHERE id = '0f80cc05-88e9-4db5-8b4a-7a909562c184';
-- FISICO · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$FUEL SWAP$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your metabolism runs slow. Your body works with small energy debts and leans on artificial stimulants to get through the day.$rsv$, sugerencia_text_en = $rsv$Add these calibrations to your routine to stabilize your energy and teach your body to generate vitality on its own.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f3_1$rsv$,'desc',$rsv$Electrolyte Load: Swap your first hydration of the day for a glass of structured water (with lemon and a quarter teaspoon of sea or Celtic salt) to switch on the electricity in your cells.$rsv$), json_build_object('id',$rsv$f3_2$rsv$,'desc',$rsv$Repair Window: Hold a minimum of 12 straight hours of overnight fasting (e.g., last meal at 20:00 and don't break it before 08:00) so your body cleans itself from the inside while you sleep.$rsv$), json_build_object('id',$rsv$f3_3$rsv$,'desc',$rsv$Room Seal: Physically turn off your home Wi-Fi router during your sleep hours to remove electromagnetic radiation from your room.$rsv$))::text) WHERE id = '29ff4722-eb53-416d-90e5-240fb781ae46';
-- FISICO · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$STRUCTURAL STABILITY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body is in balance, but static. It covers the basics of the day, but lacks the stimulus and reserve energy to make a bigger leap.$rsv$, sugerencia_text_en = $rsv$Do these tasks every day to strengthen your body and move from just surviving to truly storing energy.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f4_1$rsv$,'desc',$rsv$Grounding to Earth: Make direct physical contact (skin to soil, grass, or sand) for 10 straight minutes to discharge accumulated tension and sync your body with the planet's.$rsv$), json_build_object('id',$rsv$f4_2$rsv$,'desc',$rsv$Tension and Strength: Do 15 minutes of resistance movement (body weight, push-ups, squats, or weights) to strengthen your bones and generate internal energy.$rsv$), json_build_object('id',$rsv$f4_3$rsv$,'desc',$rsv$Light Transition: Turn off white lights (LED/fluorescent) and avoid screens without a blue-light filter 45 minutes before sleep; use only warm, red, or dim light so your body releases melatonin naturally.$rsv$), json_build_object('id',$rsv$f4_4$rsv$,'desc',$rsv$Clean Air: Avoid synthetic aerosols, commercial incense, or artificial air fresheners in your work and rest space, and ventilate daily.$rsv$))::text) WHERE id = '94ed2988-467d-4cb3-8c45-46ce251d88a2';
-- FISICO · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$METABOLIC DEFRAGMENTATION$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body has hit its limit with your current diet. It works and responds to the day's demands, but holds a level of inflammation and wear that holds you back from leveling up.$rsv$, sugerencia_text_en = $rsv$Apply these calibrations to clean up your diet and your rest, and lower the inflammation that is stealing your energy.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f5_1$rsv$,'desc',$rsv$Out with Industrial Oils: Fully eliminate heavily processed seed oils (soy, canola, sunflower). Replace them only with good fats like extra virgin olive oil or coconut oil.$rsv$), json_build_object('id',$rsv$f5_2$rsv$,'desc',$rsv$Better Water: Raise the quality of your base water. Avoid jug water. Use good-quality distilled or purified water as your base, before preparing it with lemon and sea salt.$rsv$), json_build_object('id',$rsv$f5_3$rsv$,'desc',$rsv$Fixed Rest Time: Set a non-negotiable time to power down each night. Your body regenerates better when it goes to sleep at the same time every day, without variation.$rsv$), json_build_object('id',$rsv$f5_4$rsv$,'desc',$rsv$Out with Gluten: Remove gluten from your daily diet. Dropping this protein hugely reduces mental fog and gut inflammation, and frees up the energy trapped in digestion.$rsv$))::text) WHERE id = '7ce157a3-86ab-4b7b-957a-7d40122b5acc';
-- FISICO · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SILICON TRANSITION$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body has started to transform. It already tells apart what harms it, but it needs firm discipline to stabilize the strength of your muscles.$rsv$, sugerencia_text_en = $rsv$Apply these precise directives to expose your body to controlled effort and turn movement into real strength and energy.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f6_1$rsv$,'desc',$rsv$Zero Refined Sugar: Cut refined sugar completely. Removing that artificial glucose eliminates insulin spikes and stabilizes your nervous system on a firm, powerful line.$rsv$), json_build_object('id',$rsv$f6_2$rsv$,'desc',$rsv$Constant Tension: Anchor an impact or strength workout (e.g., weights or combat) at least 3 or 4 times a week. Exposing bone and muscle to programmed effort forces your body to become denser and stronger.$rsv$), json_build_object('id',$rsv$f6_3$rsv$,'desc',$rsv$Magnesium at Night: Add a well-absorbed magnesium every night. This mineral is the key that lets your nervous system release the alert and enter deep, restorative rest.$rsv$), json_build_object('id',$rsv$f6_4$rsv$,'desc',$rsv$Breathing Under Pressure: In high-pressure moments during the day, deliberately hold a nasal breath of 5 seconds in and 5 seconds out, without stopping what you are doing.$rsv$))::text) WHERE id = 'e1a00ff9-f0dd-4530-af57-92fd3413fb77';
-- FISICO · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$BASE GEOMETRY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body is consolidating. It has already shed its heaviness, but it needs firm discipline to hold high energy without your nervous system destabilizing.$rsv$, sugerencia_text_en = $rsv$Anchor these routines of cleanliness and order to shield your energy and make your body practically unbreakable.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f7_1$rsv$,'desc',$rsv$Wider Fasting: Take your intermittent fasting to a minimum of 14 to 16 hours a day. Force your body to draw energy from its own fat reserves and clean itself at the cellular level before the first meal.$rsv$), json_build_object('id',$rsv$f7_2$rsv$,'desc',$rsv$Full Product Cleanup: Do the definitive purge of your chemical environment. Move 100% of your skin-contact products (soaps, creams, toothpastes) to natural options. Zero toxins crossing your skin.$rsv$), json_build_object('id',$rsv$f7_3$rsv$,'desc',$rsv$Permanent Nasal Breathing: Fully eliminate unconscious mouth breathing. Nasal, silent breathing from the abdomen becomes your normal state 24/7, even when exercising at medium intensity; leave the mouth only for speaking or extreme effort.$rsv$), json_build_object('id',$rsv$f7_4$rsv$,'desc',$rsv$Sanctuary Room: Turn your room into a sealed refuge. Beyond turning off Wi-Fi and blue light, ensure total darkness (blackout curtains or an eye mask) and a cool temperature to enter deep sleep at once.$rsv$))::text) WHERE id = '3b08cadd-3cf0-4c05-adfa-920f5263853e';
-- FISICO · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$MAGNETIC RESONANCE$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body has stabilized and uses energy well. The surplus you build up needs an outlet through movement, or it turns into tension. You are now ready to capture light like an antenna.$rsv$, sugerencia_text_en = $rsv$Apply these high-impact anchors to optimize your internal fluids and align your biological clock with the cycles of day and night.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f8_1$rsv$,'desc',$rsv$Pure Structured Water: Leave ordinary water behind. Make 100% of your hydration crystalline purified water, prepared with lemon and Celtic sea salt, so your body conducts energy permanently.$rsv$), json_build_object('id',$rsv$f8_2$rsv$,'desc',$rsv$Solar Clock: Add to the morning sunlight a conscious exposure at noon and at sunset. Capturing all three moments of sunlight tunes your internal clock and maximizes your natural vitamin D production.$rsv$), json_build_object('id',$rsv$f8_3$rsv$,'desc',$rsv$Complex Movement: Add a physically demanding discipline that challenges the brain (martial arts like Jiu-Jitsu, or olympic/heavy lifting). Force your nervous system and your muscles to communicate fast and with precision.$rsv$), json_build_object('id',$rsv$f8_4$rsv$,'desc',$rsv$Level 1 Supplementation: Bring in the foundations to optimize your body: Vitamin D3 with K2 to direct calcium to your bones, and high-purity extra virgin olive oil as a lubricant for your neural and cellular network.$rsv$))::text) WHERE id = '83160d0f-ec9b-4fae-9416-9bb2ac496602';
-- FISICO · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SILICON ARCHITECTURE$rsv$, descripcion_corta_en = $rsv$Execute these advanced calibrations to bring your cells to maximum coherence. At this level, the goal is to hold long windows of total focus and calm without losing energy.$rsv$, alerta_text_en = $rsv$Your energy is high and your body conducts optimally. It rejects industrial food by instinct. Your structure is solid, but it needs precision adjustments to touch sustained maximum coherence.$rsv$, sugerencia_text_en = $rsv$Add these precision anchors to your day to hold your energy without leaks. Do not chase perfection: chase consistency.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f9_1$rsv$,'desc',$rsv$Level 2 Supplementation: Add the advanced minerals. Bring in boron and pure silicon (diatomaceous earth) to strengthen your bones and decalcify your pineal gland. Add Vitamin B12 to secure good conduction in your nervous system.$rsv$), json_build_object('id',$rsv$f9_2$rsv$,'desc',$rsv$Pre-Dawn Waking: Move the start of your day to the deep pre-dawn hours (between 12:00 AM and 3:30 AM). Use total silence to create, meditate, and work without a single interference.$rsv$), json_build_object('id',$rsv$f9_3$rsv$,'desc',$rsv$Extreme Physical Discipline: Put your body through a relentless, constant physical discipline. Keep the regularity in a martial art (like Jiu-Jitsu) or in weights. Use extreme physical effort to dissolve the ego and keep your mind sharp.$rsv$), json_build_object('id',$rsv$f9_4$rsv$,'desc',$rsv$Deep Fasting: Master the windows of prolonged fasting. Use it not only to clean the body, but to focus 100% of your energy and blood flow on your brain while you create your projects.$rsv$))::text) WHERE id = '09b4eaee-bbc2-4293-b785-908c90d36eee';
-- FISICO · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$SUPERCONDUCTIVITY (ZERO STATE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your body operates in Zero Friction. It is practically unbreakable. It no longer just digests: it assimilates. Your energy is clean, sustained, and expansive. You have left heaviness fully behind.$rsv$, sugerencia_text_en = $rsv$You have reached the peak of your vitality. You are a living solar panel. Your only task is to keep the circuit closed and protect your balance every day.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$f10_1$rsv$,'desc',$rsv$Early Shutdown: Keep your room sacred. Power down your system early (e.g., 8:00 PM) without exception. Fully respecting your recovery window secures your pre-dawn ignition the next day.$rsv$), json_build_object('id',$rsv$f10_2$rsv$,'desc',$rsv$Total Exclusion: Hold the seal against what harms you. Sustain the total exclusion of sugar, gluten, soy, and industrial oils. Your body operates like a tube of light: the slightest density is detected and must go out.$rsv$), json_build_object('id',$rsv$f10_3$rsv$,'desc',$rsv$The Water Loop: Preserve the superior quality of your internal fluids. Keep your base hydration as only structured, distilled, remineralized, and energized water.$rsv$), json_build_object('id',$rsv$f10_4$rsv$,'desc',$rsv$Continuous Sun and Earth: The daily anchor to the Sun (light) and to the Earth (contact with the ground) stops being a task and becomes breathing. Your body recognizes itself as part of nature and recharges energy directly from the environment, with no intermediaries.$rsv$))::text) WHERE id = '9d05338e-dd61-4466-bd2b-af5cd6355463';
-- MENTAL · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$MEMORY DEFRAGMENTATION (BASE RESET)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your mind is saturated and scattered. Your attention is hijacked by the outside world and by the quick reward of screens. The voice you talk to yourself with runs like constant sabotage, leaving you paralyzed between anxiety and guilt.$rsv$, sugerencia_text_en = $rsv$Add these small anchors to stop the leak of attention. The goal is not to reach mental peace all at once, but to force that tyrant voice to pause and take back control of your own mind.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m1$rsv$,'desc',$rsv$Startup Lock: You are forbidden to touch your phone or any screen during the first 30 minutes after you open your eyes. Let your brain wake up calmly before you inject it with the noise of the outside world.$rsv$), json_build_object('id',$rsv$m2$rsv$,'desc',$rsv$Mental Dump: When you feel anxiety or paralysis blocking you, grab paper and pencil. Write out a list of absolutely everything that worries you, no filters. Get that data out of your head and force it onto the paper to free up mental space.$rsv$), json_build_object('id',$rsv$m3$rsv$,'desc',$rsv$Interrupt the Tyrant Voice: Identify the insult or destructive phrase you repeat to yourself the most ("I'm a failure", "I can't"). When you hear that voice in your head, cut it off physically: say "STOP" out loud or clap once. Break the loop mechanically.$rsv$))::text) WHERE id = '25a2b422-9659-41eb-a83a-bc27bb560d06';
-- MENTAL · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CLOSING TABS (STATIC PURGE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your mind is chronically overloaded. You live with too many processes open at once, draining your energy. You consume too much dense information and your mind constantly travels to the future (worry), wearing down your presence in the now.$rsv$, sugerencia_text_en = $rsv$Apply these practices daily to clean up what you let in. Start purging the noise of the world so the signal of your own intuition can find a clear channel.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m2_1$rsv$,'desc',$rsv$Information Diet, Level 1: Run an immediate purge on your social media. Unfollow or mute at least 10 accounts that generate noise, fear, outrage, or toxic comparison for you. Protect the border of what you take in through your eyes.$rsv$), json_build_object('id',$rsv$m2_2$rsv$,'desc',$rsv$One Thing at a Time: At least once a day, choose a mechanical task (eating, washing dishes, walking, or writing a report) and do it in absolute silence. No music, podcasts, or videos in the background. Train your mind to hold a single thing at a time.$rsv$), json_build_object('id',$rsv$m2_3$rsv$,'desc',$rsv$Anchor to the Present: When you notice your mind has been trapped in the future (anxiety) or the past (chewing on something) for minutes, use touch to come back. Touch a physical object (your desk, your mug, a texture), feel its temperature, and breathe. Return your attention to the same place your body is.$rsv$), json_build_object('id',$rsv$m2_4$rsv$,'desc',$rsv$Limit on Indecision (2-Minute Rule): For low-impact daily micro-decisions (what to eat, what to wear, which email to answer first), set yourself a mental limit of 120 seconds. Decide before time runs out and move on. No second-guessing after you choose.$rsv$))::text) WHERE id = '3eae4fdf-06ab-4d77-af79-beec695cf7e0';
-- MENTAL · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$STATIC REDUCTION (SIGNAL ISOLATION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You function, but with a lot of tension from doubt. Your mind works, but the voice of the ego and the voice of intuition sound at the same volume, burning up a ton of energy on every decision. You lose too much mental space questioning the past and seeking approval.$rsv$, sugerencia_text_en = $rsv$Anchor these calibrations to silence the doubt that drags on. The goal is to hear your own voice, stop asking the outside world for permission, and shorten the time between analyzing a problem and getting to work on it.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m3_1$rsv$,'desc',$rsv$Approval Quarantine (Zero Consultations): The next time you have to make a medium-impact decision, you are forbidden to ask for advice or "bounce the idea" off friends, partner, or family. Evaluate the problem on your own, decide, and own the consequence. Trust your own judgment.$rsv$), json_build_object('id',$rsv$m3_2$rsv$,'desc',$rsv$Reframe Without Complaints: When a minor obstacle changes your plans for the day (traffic, a mistake, a canceled appointment), force yourself not to let out a single complaint out loud. Treat it as plain new data. Redirect your course immediately.$rsv$), json_build_object('id',$rsv$m3_3$rsv$,'desc',$rsv$Digital Cleanup: Your visual environment sets your mental load. Delete the useless icons from your desktop, remove the apps you don't use, and unsubscribe from 5 automated emails (newsletters) that only generate junk in your inbox. Order outside for calm inside.$rsv$), json_build_object('id',$rsv$m3_4$rsv$,'desc',$rsv$Shut Down Nighttime Rumination: If your mind is still trying to solve problems 60 minutes before sleep, declare a "close of the day" out loud. Recognize that your tired brain does not think clearly; let the solution ripen during sleep.$rsv$))::text) WHERE id = '72895713-3609-49cd-a2cf-f05ed8fd5aa7';
-- MENTAL · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CONTROLLED LATENCY AND PLASTICITY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You only function well under pressure. You reach sharp focus when there is stress or a deadline, but in free time or without urgency your mind scatters, hunts for distraction, and struggles to stay in the present.$rsv$, sugerencia_text_en = $rsv$Apply the following directives to train your mind to tolerate blank space without panicking. Move from focus forced by urgency to concentration you choose by your own will.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m4_1$rsv$,'desc',$rsv$Emptiness Training (Zero Stimuli): Once a day, sit or lie down for 5 minutes doing absolutely nothing. No meditating, listening to music, checking your phone, or reading. Just you and the silence of the room. Train your nervous system to do nothing without feeling unproductive.$rsv$), json_build_object('id',$rsv$m4_2$rsv$,'desc',$rsv$Protected Focus Block: Set aside at least one 60-minute window a day for deep work. During that block, your phone must be in another room and all your notifications off. Do the task without allowing yourself a single interruption from outside.$rsv$), json_build_object('id',$rsv$m4_3$rsv$,'desc',$rsv$Review Your Certainties: Identify a belief (political, ideological, or technical) that you defend with a lot of passion. Spend 15 minutes reading or listening to a strong argument from the opposing side without building a defense in your head. Train your mind to take in new information without feeling attacked.$rsv$), json_build_object('id',$rsv$m4_4$rsv$,'desc',$rsv$Calibrate Your Inner Voice: Change the way you talk to yourself. Replace the weight of "I have to..." (e.g. "I have to train", "I have to work") with "I choose..." (e.g. "I choose to strengthen my body", "I choose to move this project forward"). Hand the authority back to your will.$rsv$))::text) WHERE id = '4a23e801-4605-422c-843f-22810e7d075c';
-- MENTAL · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$AWAKENING OF THE OBSERVER (BROADBAND)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You reached a breaking point. You are starting to recognize that you are not the noise of your mind. Your capacity to change is switching on and you accept changes of plan with less tension, but the voice of the "inner judge" still manages to take you over when there is stress or fatigue.$rsv$, sugerencia_text_en = $rsv$Apply these calibrations to strengthen your position as the Observer. The goal is to stop fully identifying with your invasive thoughts and start directing your attention toward creating, without falling into the victim role.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m5_1$rsv$,'desc',$rsv$Separate from the "I": When a thought of fear, of not being enough, or of chewing on something shows up, forbid yourself to say "I am anxious" or "I am afraid". Change the phrase to: "I am feeling anxiety" or "There is fear passing through me right now". Separate who you are from the passing symptom.$rsv$), json_build_object('id',$rsv$m5_2$rsv$,'desc',$rsv$Usefulness Filter (Diet Level 2): Stop consuming the traditional "news" that sells fear or mass outrage. Your mind does not need to carry the chaos of the whole world to function. If a piece of information does not teach you to create, build, or feel better, close it.$rsv$), json_build_object('id',$rsv$m5_3$rsv$,'desc',$rsv$Reframe the Obstacle: In the face of a mistake or a stop in reality, you are forbidden to look for someone to blame (neither yourself nor your surroundings). Ask yourself a single question: "Knowing what I now know, what is the smartest move from here?".$rsv$), json_build_object('id',$rsv$m5_4$rsv$,'desc',$rsv$Cold Execution (Without Waiting for Motivation): Choose an important task you have been putting off for days. Do it for 15 minutes from pure neutrality, without waiting to "feel motivated" to start. Prove to yourself that you can function even when you feel heavy.$rsv$))::text) WHERE id = '64222b6d-b97a-4477-945b-76a77d098d7a';
-- MENTAL · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CONSCIOUS HEALING AND PLASTICITY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your inner guardian activated. Silence begins to feel like a tool for building and not like a void that threatens you. Intuition and fear compete closely, but you still need discipline to update your beliefs without feeling you are losing a part of yourself.$rsv$, sugerencia_text_en = $rsv$Apply the following directives to clear the junk out of your mental diet for good and speed up your capacity to rewrite your own patterns. Your mind stops being your enemy and becomes a tool at your service.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m6_1$rsv$,'desc',$rsv$Let Go of Being Right (Death of the Intellectual Ego): Find a topic where you were wrong recently or where reality outdid your logic. Accept it out loud in front of another person: "You were right, I was wrong. I'm changing my stance". Let go of the need to "be right".$rsv$), json_build_object('id',$rsv$m6_2$rsv$,'desc',$rsv$Single-Window Sanctuary: As training, for 2 hours of your workday, force yourself to keep a single window open on your monitor. Close the rest. That physical signal of total order will force your mind to mirror that laser focus.$rsv$), json_build_object('id',$rsv$m6_3$rsv$,'desc',$rsv$Vow to Not Judge: For 24 hours, suspend all judgment about the way others run their lives (how they dress, how they talk, what they eat). Observe it as neutral data. Save the energy you spent evaluating other people's behavior.$rsv$), json_build_object('id',$rsv$m6_4$rsv$,'desc',$rsv$The Intuitive Leap (Turn Off Logic): Make a decision today (small or medium) based only on what your intuition dictates (the body's first impulse), deliberately ignoring the list of pros and cons. Let your inner wisdom drive without asking the analytical mind for permission.$rsv$))::text) WHERE id = '4bc9c194-857b-48d2-82af-5b66d8ba510b';
-- MENTAL · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ARCHITECTURE OF FOCUS$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your attention is protected. You work in blocks of deep concentration and the voice you talk to yourself with went from judge to strategist. Your mind inhabits the present, but it still needs a wall around it to keep from losing focus to the stimuli left over from your old habits.$rsv$, sugerencia_text_en = $rsv$Anchor these calibrations so that defending your focus becomes automatic. The goal is for absolute concentration to stop being a conscious effort and become your natural way of functioning.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m7_1$rsv$,'desc',$rsv$Wall of Attention: Set at least one day a week for a "partial digital fast". During that day, passive consumption is forbidden; your devices are used only to create, build, or design.$rsv$), json_build_object('id',$rsv$m7_2$rsv$,'desc',$rsv$Recalculate Your Inner Voice: When you make a mistake, you are forbidden to use adjectives that define you ("I was stupid", "I'm slow"). Limit your inner voice to purely practical language: "There was a failure. The move was wrong. Adjusting the route now".$rsv$), json_build_object('id',$rsv$m7_3$rsv$,'desc',$rsv$Anchoring in Time: Use the past only as a library of lessons and the future only as a compass for direction. If you notice you have spent more than 5 minutes imagining scenarios you cannot control today, cut that movie off out loud: "Insufficient information. Returning to the present".$rsv$), json_build_object('id',$rsv$m7_4$rsv$,'desc',$rsv$Solve by the Essential: In the face of a complex decision, trim 80% of the secondary variables. Identify the main "bottleneck" and decide based only on clearing that path. Ignore the noise around it and execute.$rsv$))::text) WHERE id = 'ecd83e96-8e57-457a-b9ba-e890f456f2e0';
-- MENTAL · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$LIQUID NEUROPLASTICITY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your mind processes fast. The attachment to your fixed ideas is dissolving. Your decisions are fast, firm, and with no noise afterward. You are ready to function without the weight of the ego, flowing through obstacles without losing momentum.$rsv$, sugerencia_text_en = $rsv$Apply these high-level practices to make your mind like water. A liquid mind takes the shape of any problem instantly, solves it from within, and keeps its course without resistance.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m8_1$rsv$,'desc',$rsv$Immediate Adaptation: When reality cancels a plan or drops an "error" into your design, forbid yourself to stay frustrated for long. You have exactly 60 seconds to acknowledge the fall, and by second 61 you must already be setting the recovery plan in motion.$rsv$), json_build_object('id',$rsv$m8_2$rsv$,'desc',$rsv$Let Go of the Obsolete: Identify a tactic, a work habit, or a belief that brought you to your current level of success but no longer fits your next expansion. Let it go today without sentimental attachment. What got you here is not what will take you to the next level.$rsv$), json_build_object('id',$rsv$m8_3$rsv$,'desc',$rsv$Offload Your Memory: Empty your mind of "things to remember". Use a reliable external system (a digital second brain, a physical notepad) to store to-dos and data. Your mind should be used only to create and think, not to store.$rsv$), json_build_object('id',$rsv$m8_4$rsv$,'desc',$rsv$Intuitive Execution: At a crossroads where logic marks the safe path but your intuition demands the leap, take the leap without asking your analytical side for permission. Train your mind to trust fully in the first signal from your inner radar, without generating doubts afterward.$rsv$))::text) WHERE id = '4fb949a2-3571-46d5-88c1-bb0f72d5cd0f';
-- MENTAL · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$CODE SOVEREIGNTY$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your mind flows without obstacles. It is shielded against the noise of the outside. The voice you talk to yourself with has shrunk to practical data and your capacity to adapt is nearly instant. Your system rejects doubt and scattering, but it needs to sustain the energy across long windows of pure creation.$rsv$, sugerencia_text_en = $rsv$Apply these advanced directives to crystallize your mental clarity. The goal is for reality to respond to your energy, shortening the distance between the thought and its materialization.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m9_1$rsv$,'desc',$rsv$Total Isolation (Absolute Diet): Take the noise in what you consume to zero. Chaos, news, or passive entertainment reduced to 0%. Your mind should only absorb high-value knowledge, beauty, or silence.$rsv$), json_build_object('id',$rsv$m9_2$rsv$,'desc',$rsv$Transmute the "Error": When reality drops a stop into your plans, force yourself not to see it as "an obstacle to go around". Read it instantly as a better coordinate that life just opened for you. Use the momentum of the obstacle itself to accelerate.$rsv$), json_build_object('id',$rsv$m9_3$rsv$,'desc',$rsv$Death of Doubt: Turn off the "what if...?" in your mind for good. Once you execute a decision based on intuition and analysis, forbid any review backward. The decision you made is, by default, the right decision.$rsv$), json_build_object('id',$rsv$m9_4$rsv$,'desc',$rsv$Get Used to Your Best Version: When you live through big leaps of clarity, abundance, or success, your nervous system may try to sabotage the experience out of its habit of scarcity. Hold your course firm. Recognize abundance as your natural state, not as a rarity.$rsv$))::text) WHERE id = 'd06fd886-0a50-445d-a1df-5aa9d6c2cde3';
-- MENTAL · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ANECHOIC CHAMBER (STATE ZERO)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your mind reached total calm. Absolute silence. Emptiness. The inner voice went quiet. Your mind is a black screen that only lights up to project and execute what you decide from consciousness. Laser attention, unbreakable.$rsv$, sugerencia_text_en = $rsv$You reached the total calm of the mind. You are the absolute owner of your path. Your only task is to sustain this channel of maximum clarity, letting your inner wisdom drive your body without the ego dropping in a single bit of interference.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$m10_1$rsv$,'desc',$rsv$Permanent Direct Connection: Eliminate the "negotiation" phase with your logical mind. The ego is relegated to a warning panel only. The orders from your inner radar (intuition) are executed with immediate certainty, without asking the outside world for permission.$rsv$), json_build_object('id',$rsv$m10_2$rsv$,'desc',$rsv$Turn Off Logic (Zero Rumination): Outside the blocks of work and creation, your mind should stay off. Hold that state of total silence. Walk, eat, and breathe without verbalizing a single thought in your head. Absolute presence in the moment.$rsv$), json_build_object('id',$rsv$m10_3$rsv$,'desc',$rsv$Perfect Mirror in the Face of Chaos: Observe any level of outer chaos (crises, other people's collapses, emergencies) without a single idea in your mind being disturbed. You are the point of gravity; chaos spins around you, but it never crosses into your attention.$rsv$), json_build_object('id',$rsv$m10_4$rsv$,'desc',$rsv$Materialize from Clarity: Give up excessive physical effort. Understand that 90% of the work is resolved in the mind before you touch the keyboard or the material world. Operate with the absolute certainty that life is arranging everything to match your mental clarity.$rsv$))::text) WHERE id = 'd9278d07-1252-4d68-a203-7c04e01b966a';
-- ORBITA · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$DRAIN TOURNIQUET (NETWORK QUARANTINE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows a collapse in your bonds and a severe energy leak. Your system hands all its vitality to relationships that work like black holes. You live with a mask on 24 hours a day out of fear of not fitting in, and you get contaminated instantly by everyone else's wear and tear.$rsv$, sugerencia_text_en = $rsv$Add these shock anchors to stop the massive energy leak. The goal is not to improve your current relationships, but to isolate your center so your nervous system remembers what your own energy feels like when no one is draining it.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o1_1$rsv$,'desc',$rsv$Contagion Quarantine: From this moment on, you are forbidden to join, nod along to, or listen to sessions of complaint, gossip, or victimhood. If someone around you starts up with that frequency, your order is to cut it off cold: stand up and leave the room, or say straight out "I don't have energy for this topic today."$rsv$), json_build_object('id',$rsv$o1_2$rsv$,'desc',$rsv$Map of the Leak: Take a sheet of paper and write down the names of the 3 people you interact with most who leave you physically exhausted after seeing them. Look at those relationships not as bonds of love, but as cables that drain your energy. Recognizing who drains you is the first step to breaking free.$rsv$), json_build_object('id',$rsv$o1_3$rsv$,'desc',$rsv$Small Break of the Mask: Once in the next 24 hours, when you are about to say "yes" or smile out of obligation in a social situation, force yourself to hold neutrality. Do not fake the smile. Do not give the pleasing answer. Let others feel the discomfort while you protect your truth.$rsv$), json_build_object('id',$rsv$o1_4$rsv$,'desc',$rsv$The Explanation Veto: When you need to cancel a commitment or refuse a favor that drains you, do it in fewer than 10 words (e.g. "I won't be able to attend, thank you"). It is forbidden to invent excuses, over-apologize, or justify your decision. Your "no" is a complete boundary.$rsv$))::text) WHERE id = '04e7cd5e-1d09-47f7-9765-f7efc20d60d1';
-- ORBITA · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$BREAK FROM ORIGIN (DISMANTLING GUILT)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows toxic loyalty and inherited obligation. You hold on to relationships out of inertia or a false sense of duty toward your family or old friends, as if you were a prisoner of your origin. Your breakups are dramatic and release threads of guilt that bend your shield.$rsv$, sugerencia_text_en = $rsv$Run these practices daily to take apart the illusion of emotional debt. You have to teach your ego that cutting off what wears you down is not selfishness, but an act of survival to sustain what you are building.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o2_1$rsv$,'desc',$rsv$Canceling the Inherited Debt: Identify a family event, gathering, or tradition you attend purely out of "cultural obligation" that you know will sink you. Cancel your attendance today. Receive the initial guilt in your body, breathe it, and watch how, after a few minutes, that guilt transforms into an enormous release of mental space.$rsv$), json_build_object('id',$rsv$o2_2$rsv$,'desc',$rsv$Stop the Social Begging: Review your conversations. If you are always the one who starts contact with people who take days to reply, who cancel on you, or who show no interest in your growth, cut off the supply today. Stop chasing. If the bond dies from your inaction, that bond never had real weight.$rsv$), json_build_object('id',$rsv$o2_3$rsv$,'desc',$rsv$Disconnecting from the Dramatic Mourning: If you are letting go of a toxic partner or friendship, remove all access to their trail. Absolute digital block. Do not look at their feeds, do not ask about them. Do not let your mind consume the noise of the past, so the wound in your energy can close.$rsv$), json_build_object('id',$rsv$o2_4$rsv$,'desc',$rsv$Audit of Inner Strength: Facing the emotional blackmail of a family member or acquaintance (e.g. "after all I've done for you"), force yourself to respond from calm and clarity, not from the emotion of the moment. Disarm the manipulation like this: "My love for you is real, but my energy right now is not available for this demand." Do not negotiate your boundary.$rsv$))::text) WHERE id = '6ddd8121-b731-43ac-bf43-be62307948c2';
-- ORBITA · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$DEACTIVATING ISOLATION (TACTICAL PERMEABILITY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows "wounded wolf" syndrome: an excessive, defensive independence. Your system recognizes what is toxic in your surroundings and reacts by closing all its openings. You operate in silence out of fear of conflict and refuse to show yourself vulnerable. You give chronically, but your shield keeps the network from holding you up.$rsv$, sugerencia_text_en = $rsv$Run these calibrations to transform the fear of rejection into a strategic opening. Whoever isolates loses connection. The goal is to learn to receive energy from others without feeling that your sovereignty is at risk.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o3_1$rsv$,'desc',$rsv$Active Reception: The next time someone offers you genuine help, a favor, or a compliment, you are forbidden to reject it, minimize it, or try to "pay it back" instantly. Say "Thank you, I receive it" and physically tolerate the discomfort of being supported by others.$rsv$), json_build_object('id',$rsv$o3_2$rsv$,'desc',$rsv$Open a Crack: In a setting where you would normally stay quiet so as not to bother anyone, show a flash of who you really are (an opinion about your best version, a vision of what you are building). Notice that the world does not fall apart when you let your real frequency be seen.$rsv$), json_build_object('id',$rsv$o3_3$rsv$,'desc',$rsv$Purge of Pending Resentment: Isolation feeds on the memory of past pain. Identify someone who betrayed your energy, visualize the thread that still ties you together, and declare: "The lesson is learned. I take back my energy." This is not about forgiving out of morality, but about freeing your mind.$rsv$), json_build_object('id',$rsv$o3_4$rsv$,'desc',$rsv$Transparency Audit: Assess your current surroundings. If in your relationships you operate calculating every word so you don't get hurt, those are not your people. Define in writing the exact level of transparency you need to turn off your defenses and lower your shields.$rsv$))::text) WHERE id = 'd5cfade1-0b62-4d0d-b044-249a89896ac7';
-- ORBITA · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$RELATIONAL IGNITION (BREAKING THE INERTIA)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows mechanical company and half-expression. Your closest relationships are peaceful but lifeless; functional companions who do not grow with you. You only show your true signal to a chosen few and you keep invisible threads of nostalgia toward bonds from the past.$rsv$, sugerencia_text_en = $rsv$Anchor these directives to inject strength into your connections. A merely functional orbit is not enough for your best version. You have to demand that your relationships raise your Light Index, or else move them to more distant orbits.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o4_1$rsv$,'desc',$rsv$The Evolution Test: With your primary bond or your closest friendship, open a high-level conversation today (your vision of the future, what you are building in your projects). If the other person dodges it, yawns, or trivializes it, the tension that was hidden just came into view and calls for an adjustment of distance.$rsv$), json_build_object('id',$rsv$o4_2$rsv$,'desc',$rsv$Cut the Invisible Threads: Permanently remove access to people from your past whom you check now and then out of "curiosity" or nostalgia. Your present energy and your growth have no reason to fund the memories of a stage you have already outgrown.$rsv$), json_build_object('id',$rsv$o4_3$rsv$,'desc',$rsv$End of the Diplomatic Negotiation: When your family or your group pressures you into dynamics that wear you down, drop the diplomacy that exhausts you. Set a neutral limit, with no emotional charge: "That frequency is no longer compatible with who I am today."$rsv$), json_build_object('id',$rsv$o4_4$rsv$,'desc',$rsv$Turn Up the Volume of Your Signal: Expand the radius of your energy. Choose a setting where you usually keep your voice down and share your vision openly. If the setting gets uncomfortable or rejects you, be grateful: it's confirmation that the world is pushing you, naturally, toward your true place.$rsv$))::text) WHERE id = 'd0e276ad-1f48-47b1-a4e0-93a08ed9c448';
-- ORBITA · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ORBIT TRANSITION (THE FREQUENCY SHIFT)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows an underlying tension and a change in progress. You feel the gap between your new vibration and that of your surroundings. You live in a functional isolation because you are moving away from what was pulling you down, but you do not yet connect with your new network. The temptation appears to dim your own light or to "drag" others so you don't feel alone.$rsv$, sugerencia_text_en = $rsv$Run these directives to hold the void. The gravest mistake at this stage is returning to expired bonds out of panic over temporary solitude. The void is not a punishment: it is the decompression chamber needed before the leap.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o5_1$rsv$,'desc',$rsv$Death of the Savior Syndrome: Give up today, out loud and inside, the idea of "awakening," dragging, or convincing your partner, family, or friends to see your vision. Their evolution is not your responsibility. Your only task is to shine; if their system cannot tolerate your light, the tension must force the separation, not make you dim yourself.$rsv$), json_build_object('id',$rsv$o5_2$rsv$,'desc',$rsv$The Elegant Detour: When someone who wears you down tries to dump complaints or victimhood on you, use the void in your favor. Do not argue, do not try to give "solutions" to someone who only wants to complain. Answer with a simple: "I understand that's how you see it," and withdraw your attention from the spot. Let their wear and tear slide off without touching your center.$rsv$), json_build_object('id',$rsv$o5_3$rsv$,'desc',$rsv$Tolerate the Tension of the Void: When you feel the urge to message someone from your past just to fill the silence of a Sunday afternoon, stop. Sit in that void. Tolerate the echo of your own consciousness until the panic of solitude transforms into absolute sovereignty.$rsv$), json_build_object('id',$rsv$o5_4$rsv$,'desc',$rsv$Zero Dimming of Your Light: In your unavoidable interactions with your surroundings, you are forbidden to "make yourself small" so others don't feel bad. If your victories, your vision, or your discipline unsettle their insecurities, hold firm. Let your existence be a mirror of their own conformity.$rsv$))::text) WHERE id = 'd44de7f9-2e78-4e36-ad1f-5780aa5ded5a';
-- ORBITA · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$QUANTUM PRUNING (THE CLEAN SURGERY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows the scalpel in action. You have already understood that the relationships that wear you down drain you. Your sovereignty over your own lineage is declared and the cuts become clean and practical. You start allowing yourself a certain conscious openness, learning to be supported without losing your power.$rsv$, sugerencia_text_en = $rsv$Apply these calibrations to speed up the cleansing of your energy. A deep pruning demands cutting the dead branches from the root, without guilt, without drama, with a cold clarity born of self-respect.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o6_1$rsv$,'desc',$rsv$Execute the Clean Surgery: Identify that relationship (friendship, partner, or contact) you know has already expired. Let it go today. There is no need for endless arguments or dramatic closings. Give thanks for the lesson inside, communicate the closure neutrally if necessary, and shut off the access.$rsv$), json_build_object('id',$rsv$o6_2$rsv$,'desc',$rsv$Active Family Boundary: The next time a family member demands your energy leaning on "blood and duty," exercise your sovereignty without giving long explanations. A simple "I love you, but I'm not going to take part in this" is a complete barrier. Let go of the need to be understood.$rsv$), json_build_object('id',$rsv$o6_3$rsv$,'desc',$rsv$Conscious Opening Exercise: Seek out someone in your surroundings you resonate with, and ask them for advice, support, or simply to be heard. Force your "lone wolf" to lower its shields and live the experience of receiving clean energy without feeling you owe anything in return.$rsv$), json_build_object('id',$rsv$o6_4$rsv$,'desc',$rsv$Consolidate the New Standard: Draw an impassable mental boundary. Once you have removed someone who brings you down from your surroundings, you are forbidden to readmit them out of pity or empty promises of change. The decompression chamber only moves forward.$rsv$))::text) WHERE id = '431f1bb5-3972-449c-9ff5-e1b232b77a4d';
-- ORBITA · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$TUNING BY AFFINITY (ACTIVE RESONANCE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows open communication and natural attunement. The connection with your close circle is conscious and respects the other's freedom. You no longer force interactions or attend events out of obligation. You naturally cross paths with people who vibrate on your same frequency.$rsv$, sugerencia_text_en = $rsv$Run these calibrations to fine-tune the purity of your signal. The goal is to stop "making contacts" out of ego or need, and start weaving your network purely through the resonance of your work and your frequency.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o7_1$rsv$,'desc',$rsv$Transmission Without Apology: In your next interaction, forbid yourself to use phrases that soften your vision ("well, it's just my idea," "maybe I'm crazy but..."). Share what's yours with absolute confidence. If it makes someone uncomfortable, that's a sign you're in the wrong room, not that your message is wrong.$rsv$), json_build_object('id',$rsv$o7_2$rsv$,'desc',$rsv$End of the Relational Effort: Identify any relationship or alliance (friendship or partner) where you feel you are always the one who starts, pushes, or "pulls" the cart. Withdraw that push today. If the relationship doesn't hold up through mutual interest, let the natural distance do its work.$rsv$), json_build_object('id',$rsv$o7_3$rsv$,'desc',$rsv$Intimate Resonance Calibration: With your primary bond, open a space of conscious growth. Dedicate one hour a week, strictly, to review how you are doing together, detect energy leaks, and reorient your course, working as two aligned engines and not as mere roommates.$rsv$), json_build_object('id',$rsv$o7_4$rsv$,'desc',$rsv$Active Opening: Ask for your network's support on a task or process you would normally do alone. Show your shield that lowering your defenses in front of aligned people is not weakness, but a smart way to make use of everyone's energy.$rsv$))::text) WHERE id = '7383b275-d7b3-4a63-badd-b7247619358f';
-- ORBITA · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ECOSYSTEM OF SOVEREIGNS (MAGNETIC REPULSION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows the formation of a force field. Your circle is small, impenetrable, and of the highest quality. You give from abundance, with zero guilt. There is a natural repulsion effect: your light is so dense that those who drain and those who live in victimhood exile themselves from your orbit, because the tension becomes unbearable for them.$rsv$, sugerencia_text_en = $rsv$Apply these elite protocols to shield your network. At this level, you cannot let in a single Trojan horse. Your surroundings are a closed space where only the language of creating and materializing is spoken.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o8_1$rsv$,'desc',$rsv$High-Quality Pruning: Do one last review of your first circle of trust. If you detect someone who still responds to your successes with hidden envy, chronic skepticism, or passive-aggressive comments, withdraw their access to your center. Your first circle should be made up only of transformed people who celebrate your leap.$rsv$), json_build_object('id',$rsv$o8_2$rsv$,'desc',$rsv$Irreverent Presence: When you enter a physical or digital space dominated by the wear and tear of the surroundings, do not adapt to its shape. Hold your Light Index at its maximum. Make the whole room feel your frequency. The setting will rearrange itself to receive you or it will expel you naturally. Both are victories.$rsv$), json_build_object('id',$rsv$o8_3$rsv$,'desc',$rsv$Delivery of Overabundance: Deliver value, time, or knowledge to someone in your surroundings generously, but with a strict internal rule: expect nothing in return. Train your system to give purely because you are overflowing with energy, eliminating the model of debt and obligation.$rsv$), json_build_object('id',$rsv$o8_4$rsv$,'desc',$rsv$Shield Maintenance: When you detect the slightest vibration of manipulation, gossip, or drama entering your radar, do not use the elegant detour; use the hard cut. "This conversation lowers the energy. That's it." Let your intolerance of the toxic be legendary and unbreakable in your surroundings.$rsv$))::text) WHERE id = 'cfa9a2cd-606c-433b-8beb-6c5cbcb816ba';
-- ORBITA · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$GRAVITATIONAL FORCE (FIELD MULTIPLIER)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows the formation of a core of extremely high density. You are a Field Multiplier. The intimate union with your primary bond (partner or business partner) generates a reaction that defies simple addition: you do not add up, you multiply. You no longer seek connections; you create realities that draw the right people toward your orbit inevitably.$rsv$, sugerencia_text_en = $rsv$Run these master directives to operate as the sun of your own system. You no longer need to "protect" yourself from your surroundings, because your energy is strong enough to rewrite the rules of the space you inhabit.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o9_1$rsv$,'desc',$rsv$Ignite the Twin Engines: If you have a primary bond of high resonance, eliminate the friction of daily life. Design an agreement where the weaknesses of one are automatically covered by the strengths of the other. Let the relationship stop being a space of "emotional maintenance" and become a chamber that accelerates you both.$rsv$), json_build_object('id',$rsv$o9_2$rsv$,'desc',$rsv$Cancel the Search: Eliminate the last trace of effort to attract allies, clients, or people. Your only job is to expand your own mass (your knowledge, your peace, your work). As you increase your density, the orbit of the right people will adjust toward you on its own.$rsv$), json_build_object('id',$rsv$o9_3$rsv$,'desc',$rsv$Elevate with Your Presence: Allow your mere existence to change the room. You don't need to talk about your best version to transmit it. Enter spaces holding an absolute anchor in the present moment. Your silence and your posture should be enough to raise the energy of those around you.$rsv$), json_build_object('id',$rsv$o9_4$rsv$,'desc',$rsv$Natural Filtering: Accept that, as your light grows, it will cast longer shadows on those who have not yet healed. If someone close reacts with irrational hostility to your growth, do not take it personally. Your light simply illuminated their own wounds. Hold your course forward and let your surroundings purify themselves.$rsv$))::text) WHERE id = '1f09a930-9039-4876-9643-b5bea29cc225';
-- ORBITA · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$QUANTUM ENTANGLEMENT (ZERO STATE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$The reading shows Zero Friction in your relationships. Your network runs with perfect backup. You give and receive energy without resistance. Isolation and dependence no longer exist; you operate in pure harmony with the whole. You are the living core: your presence nourishes the network, and the network sustains you with exact precision.$rsv$, sugerencia_text_en = $rsv$You have reached the Zero State in your relationships. Your energy is at once unbreakable and open. You are the sovereign of your surroundings. Hold the channel open and allow love, as a living force and not as attachment, to flow through you.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$o10_1$rsv$,'desc',$rsv$Zero Friction Harmony: Turn off the internal calculator of "who gives more." In the Zero State, giving and receiving are exactly the same movement. Allow your surroundings to nourish you naturally when you need it, knowing that by receiving you are letting another person expand their own light.$rsv$), json_build_object('id',$rsv$o10_2$rsv$,'desc',$rsv$Release and Rebirth Instantly: If a connection must end, let death and rebirth happen at once. Zero prolonged mourning. The separation happens in real time and the energy released from that broken bond transforms in the very same instant into a new leap on your path. Your signature is that of staying unshaken.$rsv$), json_build_object('id',$rsv$o10_3$rsv$,'desc',$rsv$Immunity to Separation: Understand that, deep down, no one enters or leaves your field. Physical attachment disappears because you know that the connection with people of your same frequency transcends geography and time. Physical distance does not diminish the strength of the connection.$rsv$), json_build_object('id',$rsv$o10_4$rsv$,'desc',$rsv$Radiate from the Mother Network: Recognize your place. You are not just a person navigating your surroundings; you are the seed of something new. Every relationship you purify, every boundary you set, and every engine you ignite radiates your best version toward the rest of the planet. Your close network is the prototype of a new world.$rsv$))::text) WHERE id = 'c7fa0ff7-9503-4719-9bf9-022890796dc7';
-- VECTOR · fase 1
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ENTROPIC SUPPLY CUTOFF (DISCONNECTING FROM THE CAGE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You are fully surrendered and directionless. You give 100% of your energy to holding up a life you did not choose, living with chronic boredom. The fire in your chest is out and you cannot see any future of your own.$rsv$, sugerencia_text_en = $rsv$Add these small shock anchors. The immediate goal is not to find your purpose, but to force yourself to feel the real emptiness, without distractions, so your deepest survival instinct switches back on.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v1_1$rsv$,'desc',$rsv$Reclaim your coordinate: You are forbidden to hand 100% of your day to the outside world. Starting today, "steal" 30 non-negotiable minutes from your routine (get up earlier or isolate yourself). In those 30 minutes you do nothing productive for others: it is your emptiness space to sit in silence and remember that you are a person, not a part of the machine.$rsv$), json_build_object('id',$rsv$v1_2$rsv$,'desc',$rsv$Cut the anesthesia: Identify the mechanism you use when you get home to "shut off" the exhaustion or burnout from work (alcohol, endless scrolling, junk food). Today, when you feel the urge to numb yourself, forbid it for 15 minutes. Sit in a chair, in silence, and feel the frustration of your current reality raw and physical. Use that discomfort as a blow that wakes you up.$rsv$), json_build_object('id',$rsv$v1_3$rsv$,'desc',$rsv$Map your cage: Take a piece of paper and write, with no false positivity, everything you hate about your current life: the schedule, the boss, the place, the lack of meaning. Force your mind to look its own prison in the face so your brain stops justifying it.$rsv$))::text) WHERE id = '967e3b13-d55b-409d-bb59-d89f0e1e09b3';
-- VECTOR · fase 2
UPDATE public.libreria_protocolos SET titulo_en = $rsv$IGNITION OF DEAD CODE (BREAKING CONFORMITY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You survive numbed. You run on forced discipline or on the fear of collapsing. You keep your real talents in a "waiting room" because the terror of losing your false security paralyzes you. There is strong self-sabotage that stops you from starting your own thing.$rsv$, sugerencia_text_en = $rsv$Do these exercises daily to inject small doses of tension into your painful comfort. You have to teach your nervous system that trying to grow is less dangerous than rotting in inertia.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v2_1$rsv$,'desc',$rsv$Design your "future to avoid": Since you still cannot see clearly what you want to build, use the reverse path. Write in full detail the greyest, most catastrophic, most depressing future waiting for you in 5 years if you do not change your course today. Use the fear of that future as fuel to start.$rsv$), json_build_object('id',$rsv$v2_2$rsv$,'desc',$rsv$15 minutes of your talent: You have a talent you are suppressing (writing, designing, speaking, building). Force yourself to practice exactly that skill for 15 minutes a day. It does not matter if it comes out badly or if it makes no money: it is a direct order to keep that real talent inside you alive.$rsv$), json_build_object('id',$rsv$v2_3$rsv$,'desc',$rsv$Dismantle false gratitude: Stop repeating that "at least you have a job" to justify an environment that drains your soul. You are forbidden to use gratitude as an excuse to settle. Be grateful that you breathe, but declare yourself in total rebellion against your stagnation.$rsv$), json_build_object('id',$rsv$v2_4$rsv$,'desc',$rsv$The minimum leap: To break the starting block, use the "just touch it" rule. If you want to start writing or studying a new idea, your only goal for the day is to open the program or the book. Just touch it. Remove the pressure of "finishing the work" and pour all your energy into simply turning on the engine.$rsv$))::text) WHERE id = '4982937f-dd99-4bba-b204-6c48a67e1eca';
-- VECTOR · fase 3
UPDATE public.libreria_protocolos SET titulo_en = $rsv$DESTABILIZING THE WHEEL (THE THERMODYNAMIC SPARK)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You function, but without spark. You are efficient, yet you operate in a purely mental and transactional way. You use only part of your talent and deliver standard value that does not truly reach anyone. You measure your future with goals the environment imposes on you, not with the work you want to build.$rsv$, sugerencia_text_en = $rsv$Anchor these calibrations to break the mechanical routine. The goal is to stop being an efficient operator of the system and start putting your own mark on what you do, reactivating the fire in your chest.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v3_1$rsv$,'desc',$rsv$Clean out your borrowed goals: Write your three main objectives for today. If any of them is based only on status, on accumulating things, or on seeking outside approval, cross it out. Replace it right away with a goal that builds something of your own (e.g. "Finish the first prototype of my project", "Grow my base").$rsv$), json_build_object('id',$rsv$v3_2$rsv$,'desc',$rsv$Smuggle in your talent: In your daily mechanical work, you are forbidden to deliver a "standard" result. Take a routine task and add 10% of your hidden talent. If you are designing something basic, secretly add a layer of careful, personal aesthetic. Force the world to receive your true frequency, even if no one asked for it.$rsv$), json_build_object('id',$rsv$v3_3$rsv$,'desc',$rsv$Interrupt the cold calculation: Before you start your work block, check how your chest feels. If you notice the weight of obligation, do not start right away. Breathe 10 times with your attention on the center of your chest until you feel a slight warmth. Work from that physical energy, not from cold calculation.$rsv$), json_build_object('id',$rsv$v3_4$rsv$,'desc',$rsv$Review your real impact: Analyze your last client or project. If all that happened was an exchange of money for a file or a service, you are in depletion. Design today a way to add a "hidden detail" (a note, a gesture, a touch) in your next delivery that plants a small seed of awakening in whoever receives it.$rsv$))::text) WHERE id = '57905278-02a8-4bf2-a6fc-a5e1fb25d6d6';
-- VECTOR · fase 4
UPDATE public.libreria_protocolos SET titulo_en = $rsv$BREAKING THE MIRAGE (RISK TOLERANCE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have reached the limit of the golden cage. You already have material comfort, but you live in painful conformity. You keep your vision in dense fog and lower the quality of your work to make it "commercial" or easy to digest, betraying your own truth out of fear of not being understood.$rsv$, sugerencia_text_en = $rsv$Apply these directives to shake your false security. You must teach your system that diluting who you are is a slow way of going out, and that the discomfort of being authentic is worth more than a success with no soul.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v4_1$rsv$,'desc',$rsv$Your mark, undiluted: In your next creation, text, or design, you are strictly forbidden to "soften" the message so everyone understands it. Apply the full level and rigor of your vision. If the client or the market get confused, it is their responsibility to raise their perception. Do not lower the standard yourself.$rsv$), json_build_object('id',$rsv$v4_2$rsv$,'desc',$rsv$Expose yourself today: Take a fragment of your deepest, riskiest vision (the one you keep stored because "it is not the time yet") and publish it, send it, or share it out today. Live the vertigo of being seen in your real frequency, without the commercial armor.$rsv$), json_build_object('id',$rsv$v4_3$rsv$,'desc',$rsv$Reclaim your best hour: Notice at what moment of the day your mind is sharpest and your energy is highest (your best window). If you are giving that window away to outside work or to fixing other people's lives, cancel it. That block of time is assigned solely and exclusively to building your own project.$rsv$), json_build_object('id',$rsv$v4_4$rsv$,'desc',$rsv$Train the start: When you feel the initial resistance to sit down and build your vision, cut off the mental debate. Understand that your ego hates starting. Sit down, touch the keyboard or the canvas, and forbid yourself any judgment during the first 5 minutes. Let the sheer force of the work absorb you and dissolve the tension.$rsv$))::text) WHERE id = 'b31f985d-fc9d-4d30-97b9-4a3eadfe7a30';
-- VECTOR · fase 5
UPDATE public.libreria_protocolos SET titulo_en = $rsv$MEMBRANE RUPTURE (THE AWAKENING OF FRICTION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have reached the breaking point. You no longer tolerate the emptiness of depletion. You take calculated risks, but starting toward your own vision still demands forced discipline. The fog of the future begins to clear and the first concrete blueprints of what you want to build appear.$rsv$, sugerencia_text_en = $rsv$Apply these anchors to move the energy from frustration into real building. It is time to stop being an operator who dreams and become a strategist who executes.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v5_1$rsv$,'desc',$rsv$Change lanes: Stop treating your core projects as "hobbies" or "side things". Flip the order in your head: your vision is your main job; the outside tasks that support you are just the temporary investors funding your work.$rsv$), json_build_object('id',$rsv$v5_2$rsv$,'desc',$rsv$Calculated risk: Identify a safety rope (a toxic client, a safe but soulless project, a comfort habit) and cut it this very week. Force yourself to feel a controlled emptiness so your survival energy redirects by instinct toward what you truly want to build.$rsv$), json_build_object('id',$rsv$v5_3$rsv$,'desc',$rsv$Ground the fog: You are forbidden to leave your ideas in the abstract. Spend a 60-minute block bringing your vision down to a concrete plan. Draw the map of your project, how its parts flow, and the dates when your books and platforms will become real. Force the idea to turn into something graphic and tangible.$rsv$), json_build_object('id',$rsv$v5_4$rsv$,'desc',$rsv$Work without inspiration: Kill the virus of "waiting to feel motivated". Motivation is an unstable emotion. Sit at the keyboard in your assigned time window and work, whether you write or design, with the same coldness with which you brush your teeth. Inspiration is the reward of discipline, not its requirement.$rsv$))::text) WHERE id = 'eadc20f1-4299-4fa9-a3ca-905b54c41959';
-- VECTOR · fase 6
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ARCHITECTURAL TRANSITION (THE SILICON HELM)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$You have taken the helm. Most of your attention already points to what truly lights you up. You feel a clean combustion in your chest when you create. You are starting to raise the atmosphere of those close to you, but your system needs shielding so you do not dilute your work again under outside pressure.$rsv$, sugerencia_text_en = $rsv$Apply these directives to protect the purity of your signal. Your work is no longer an experiment: it is the tool with which you are changing the consciousness of those around you.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v6_1$rsv$,'desc',$rsv$Fidelity without concessions: When you show your work or service to the world, swap the question "what do they want?" for the statement "this is what I transmit". If someone asks you to lower the quality of your design or the depth of your philosophy, decline the deal. Protect the standard of your best version.$rsv$), json_build_object('id',$rsv$v6_2$rsv$,'desc',$rsv$Live in your flow zone: Clearly detect which exact tasks put you into "productive ecstasy" (where time disappears and you feel no hunger or fatigue). Reorganize your day to guarantee that you spend at least 40% of it inside that flow zone.$rsv$), json_build_object('id',$rsv$v6_3$rsv$,'desc',$rsv$Review who you raise: Look at your last three important interactions (deliveries, deep conversations, sessions). If the other person did not leave with more clarity, energy, or awareness than they arrived with, your message is not landing. Adjust how you deliver your value so it is deeply transformative.$rsv$), json_build_object('id',$rsv$v6_4$rsv$,'desc',$rsv$Veto the commercial doubt: When you write the chapters of your books, turn off the "average reader" filter. Write for the highest, most intelligent version of each person. Trust that your work will attract, on its own, those who are already ready to receive your raw frequency.$rsv$))::text) WHERE id = '8d939789-9b58-4c36-ad8b-f884af36035a';
-- VECTOR · fase 7
UPDATE public.libreria_protocolos SET titulo_en = $rsv$VECTOR ALIGNMENT (GENETIC EXPANSION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your core talent is already lit. Your daily work demands that you use your main gift. You feel the gratitude of those around you and starting costs you very little. You have the blueprints ready and your vision is clear and concrete.$rsv$, sugerencia_text_en = $rsv$Apply these calibrations to seal your course. The goal is to eliminate any energy leak on the sides and align every breath toward making your main work real.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v7_1$rsv$,'desc',$rsv$All your energy to a single center: Decree the end of scattering. All your productive and creative energy must point to the same center of gravity (your main project). If a side project or an invitation does not nourish, fund, or expand your central vision, decline it in under 10 seconds.$rsv$), json_build_object('id',$rsv$v7_2$rsv$,'desc',$rsv$Free your gift: Delegate or automate any task that demands enormous effort without making you grow. Your work time must be reserved strictly for your zone of genius (high-quality design, ideation, and creating your work).$rsv$), json_build_object('id',$rsv$v7_3$rsv$,'desc',$rsv$Do not feed on applause: As your work reaches more people, you will start to receive applause from outside. You are forbidden to feed your ego with it. Receive the gratitude, but translate it right away as a simple "confirmation signal" that you are aimed well. Keep a cool head.$rsv$), json_build_object('id',$rsv$v7_4$rsv$,'desc',$rsv$The challenge head-on: Identify the most complex part of your current vision (e.g. integrating several pieces of your work or structuring a new book). Instead of avoiding it, make it your first work block of the day. Attack the hardest thing head-on to generate unstoppable momentum.$rsv$))::text) WHERE id = '4d6daaa3-dbfd-4c2d-b3a1-2c1936691a53';
-- VECTOR · fase 8
UPDATE public.libreria_protocolos SET titulo_en = $rsv$ACTIVE MAGNETISM (PRODUCTIVE ECSTASY)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Your fire is clean and steady. Time disappears when you create. Action springs up without forcing it: you do not push the work, you let it pass through you. You recharge with energy while you work. Your system makes no concessions and you demand that the world raise its gaze.$rsv$, sugerencia_text_en = $rsv$Apply these elite exercises to protect your flow state. At this energy level, the slightest interruption or any dilution of the message breaks the force of what you transmit.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v8_1$rsv$,'desc',$rsv$Flow sanctuary: Protect your peak creation block as if it were a sealed zone. Zero notifications, zero interactions, zero distractions. During the flow state the silence must be absolute so that time disappears.$rsv$), json_build_object('id',$rsv$v8_2$rsv$,'desc',$rsv$Non-negotiable depth: When you write the chapters of your books, hold the demand no matter the commercial pressure: the depth standard does not drop below the range of 3,500 to 5,000 words of pure content per chapter. The density and fidelity of the work are not negotiated to accommodate lazy minds.$rsv$), json_build_object('id',$rsv$v8_3$rsv$,'desc',$rsv$Give in to the pull: When that invisible attraction calls you toward the work, forbid yourself to postpone it, even if it was not on your logical schedule. If you feel the call to write or to create, obey at once. The force of purpose is more important than any agenda.$rsv$), json_build_object('id',$rsv$v8_4$rsv$,'desc',$rsv$Measure depth, not quantity: When you evaluate the impact of your work, stop measuring "how many" you reach and start measuring "how deep" you go. It is worth infinitely more to truly raise one single person toward their best version than to entertain ten thousand who are still asleep.$rsv$))::text) WHERE id = '697a1cad-6862-41b5-a8b4-719ee79237bf';
-- VECTOR · fase 9
UPDATE public.libreria_protocolos SET titulo_en = $rsv$MATRIX ALTERATION (GRAVITATIONAL ATTRACTION)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$There is total attraction toward your work. Stopping the work costs you infinitely more than starting it. Your life and your creation are now one and the same. You have an almost prophetic certainty about your future because you have already seen it clearly. Your mere presence changes the immediate reality around you.$rsv$, sugerencia_text_en = $rsv$Apply these master directives to scale the influence around you. You are no longer a participant in the system: you are an active source that raises everyone you touch.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v9_1$rsv$,'desc',$rsv$Permanent seeding: Make sure every part of your vision, your business, or your art is designed not only to be useful, but to permanently raise those who touch it. Your work must spread light as it goes.$rsv$), json_build_object('id',$rsv$v9_2$rsv$,'desc',$rsv$Fuse your life and your work: Erase the mental line between your "free" time and your "productive" time. Understand that caring for your body, nourishing yourself well, training your strength, or resting in emptiness are acts of building just as valid as working on your main work. It all feeds the same thing.$rsv$), json_build_object('id',$rsv$v9_3$rsv$,'desc',$rsv$Stop pushing: Give up completely on the energy of "pushing" or forcing results. If a project, contact, or result presents unnatural and prolonged resistance, withdraw your energy at once. Operate 100% from attraction: what is meant for you flows without tension.$rsv$), json_build_object('id',$rsv$v9_4$rsv$,'desc',$rsv$Walk with certainty: Move toward your vision without looking to the sides to measure the "competition". In your frequency, competition does not exist: there are only other people operating at different levels. Walk your course with the calm of someone who already knows how the story ends.$rsv$))::text) WHERE id = 'd9fa7cc6-c526-4d62-a5ac-59d525e46b72';
-- VECTOR · fase 10
UPDATE public.libreria_protocolos SET titulo_en = $rsv$THE SINGULARITY OF PURPOSE (ZERO STATE)$rsv$, descripcion_corta_en = $rsv$$rsv$, alerta_text_en = $rsv$Zero tension in your expansion engine. You are the architect of your own work. All your energy materializes what you are in essence. Your message is raw, firm, and perfect. Life lives itself through your creation, and you do not negotiate your energy under any circumstance.$rsv$, sugerencia_text_en = $rsv$You have reached the highest point of purpose. You are the center of your own reality. Your only logistical task is to keep the antenna clean and hold the space so everything organizes itself around your energy.$rsv$, tareas_json_en = to_jsonb(json_build_array(json_build_object('id',$rsv$v10_1$rsv$,'desc',$rsv$Pure channeling: When you write the principles of your own philosophy, assemble your systems, or design your greatest work, turn off the logical mind. Do not "think" what you create, let it drop. You are a clean channel: the genius does not belong to you, you are simply the clear vessel it uses to arrive.$rsv$), json_build_object('id',$rsv$v10_2$rsv$,'desc',$rsv$Zero tolerance for what lowers you: Reject at once and without hesitation everything that has no soul. If a place, a business proposal, or an interaction lowers your frequency, cut off contact on the spot, no matter the momentary material cost. Your world admits no depletion.$rsv$), json_build_object('id',$rsv$v10_3$rsv$,'desc',$rsv$Radiate from now: Understand that your highest vision is not something you "will achieve in the future": it is something that already exists and breathes through you today. Your simple steadiness in inhabiting a higher frequency lights up those asleep around you. Be the sun; the planets fall into orbit on their own.$rsv$), json_build_object('id',$rsv$v10_4$rsv$,'desc',$rsv$Your existence is the work: Recognize as unshakable truth that your greatest contribution to the world is not what you build, what you sell, or what you produce. Your greatest work is the pure frequency you hold within your own body. Your mere existence already raises the environment.$rsv$))::text) WHERE id = '4e256ca2-379e-4e21-8090-719fadbed47e';

COMMIT;